import json
G=[[0]*30 for _ in range(30)]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for i in range(4):
    r0=1+7*i
    for j in range(4):
        c0=1+7*j
        col=colors[i][j]
        for dr in range(5):
            for dc in range(5):
                G[r0+dr][c0+dc]=4 if dr in (0,4) or dc in (0,4) else col
    # clipped last column border
    for dr in range(5): G[r0+dr][29]=4
# clipped bottom row border
for c0 in [1,8,15,22]:
    for dc in range(5): G[29][c0+dc]=4
G[29][29]=4
# horizontal connectors: between marked tiles of same non-background color in each aligned row
for i in range(4):
    for color in set(colors[i])-{2}:
        js=[j for j,x in enumerate(colors[i]) if x==color]
        for a,b in zip(js,js[1:]):
            rr=1+7*i+2 # center of inner 3x3
            for k in range(a,b):
                # gap between tile k and k+1
                for cc in range(1+7*k+5, 1+7*(k+1)):
                    G[rr][cc]=color
# vertical
for j in range(4):
    colvals=[colors[i][j] for i in range(4)]
    for color in set(colvals)-{2}:
        ii=[i for i,x in enumerate(colvals) if x==color]
        for a,b in zip(ii,ii[1:]):
            cc=1+7*j+2
            for k in range(a,b):
                for rr in range(1+7*k+5,1+7*(k+1)):
                    G[rr][cc]=color
print(json.dumps(G))

